const Default = () => (
  // Nachbildung des realen Console-Grids: Hauptuhr-Panel ~730px breit bei
  // ~1900px Fensterbreite (50/50 Split mit "Nachfolgende Partien"),
  // volle verfügbare Höhe — damit die Uhr im gewählten Storybook-Viewport
  // genauso mitwächst wie im echten Fernkauf-Fenster.
  (<div style={{ width: "38vw", minWidth: 420, maxWidth: 730, height: "100vh", background: "var(--color-neutral-border-default)", padding: 8, boxSizing: "border-box", display: "flex" }}>
    <ActiveClockPanel />
  </div>)
);

const NarrowTablet = () => (
  <div style={{ width: 400, height: 700, background: "var(--color-neutral-border-default)", padding: 8, boxSizing: "border-box", display: "flex" }}>
    <ActiveClockPanelNarrow />
  </div>
);

const Gesperrt = () => (
  <KauftasteAnbieter gesperrt>
    <div style={{ width: "38vw", minWidth: 420, maxWidth: 730, height: "100vh", background: "var(--color-neutral-border-default)", padding: 8, boxSizing: "border-box", display: "flex" }}>
