import { useState } from "react";

const meta = {
  title: "Katalog/PriceDialog",
  parameters: { layout: "fullscreen" },
} satisfies Meta;

export default meta;
type Story = StoryObj;

/**
 * Detail-Drawer zum Hinterlegen eines Vorstellungspreises (Zielpreis) für eine Partie.
 * Öffnet sich rechts über dem Katalog, wenn der Käufer auf den €-Button in einer Zeile klickt.
 */
export const Default: Story = {
  render: () => {
    const [dialog, setDialog] = useState<DialogState>({ open: true, rowIdx: 3, price: "", menge: "", rest: false });
    return (
      <div style={{ width: "100vw", height: "100vh", position: "relative", background: "rgba(0,0,0,0.3)" }}>
        <KatalogPriceDialog
          dialog={dialog}
          setDialog={setDialog}
          prices={{}}
          onSave={() => setDialog(d => ({ ...d, open: false }))}
          onRemove={() => setDialog(d => ({ ...d, open: false }))}
          onNavigate={dir => setDialog(d => ({ ...d, rowIdx: dir === "prev" ? Math.max(0, (d.rowIdx ?? 0) - 1) : Math.min(15, (d.rowIdx ?? 0) + 1) }))}
          rowIndices={Array.from({ length: 16 }, (_, i) => i)}
